ТОЧНАЯ СХЕМА ЕДИНСТВЕННОГО ДОПУСТИМОГО ОТВЕТА:
SCHEMA_NAME: sommelier_first_turn
JSON_SCHEMA:
{
  "additionalProperties": false,
  "description": "Mobile-sized opening answer and exactly two generative suggestions.",
  "properties": {
    "content": {
      "title": "Content",
      "type": "string"
    },
    "suggestions": {
      "items": {
        "type": "string"
      },
      "maxItems": 2,
      "minItems": 2,
      "title": "Suggestions",
      "type": "array"
    }
  },
  "required": [
    "content",
    "suggestions"
  ],
  "title": "FirstTurnOutput",
  "type": "object"
}
